<script setup lang="ts">
import {computed} from 'vue'
const props=defineProps<{rows:Record<string,any>[];columns?:{key:string;label:string}[]}>()
const labels:Record<string,string>={material_id:'物料ID',material_code:'物料编码',material_name:'物料',warehouse_name:'仓库',unit:'单位',safety_stock:'安全库存',current_quantity:'当前数量',opening_quantity:'期初',in_quantity:'入库',out_quantity:'出库',closing_quantity:'期末',shortage_quantity:'缺口',required_quantity:'未领料需求',transaction_no:'流水号',source_order_no:'来源单号',transaction_type:'方向',quantity:'数量',created_at:'时间',code:'工单号',plan_no:'计划号',order_no:'订单号',status:'状态',suggested_quantity:'建议补货量',task_no:'任务号',work_order_code:'工单',attempts:'执行次数',error:'说明',creation_seconds:'自动创建耗时（秒）',finished_at:'处理时间',completed_at:'放行时间',report_quantity:'报工数量',qualified_quantity:'合格数量',report_time:'报工时间',kind:'检验类型',source_id:'来源ID'}
const values:Record<string,string>={SCRAP_HOLD:'报废冻结',REJECTED:'已驳回',DRAFT:'草稿',POSTED:'已过账',CANCELLED:'已取消',OPEN:'待处置',CLOSED:'已关闭',REWORKING:'返工中',REWORK:'返工',REJECT:'拒收',SCRAP:'整批报废',SCRAP_PENDING:'报废待执行',OVERDUE:'已逾期',LOW:'低库存',HIGH:'高库存',PURCHASE_RECEIPT:'采购入库',PURCHASE_RETURN:'供应商退货',PRODUCTION_RECEIPT:'成品入库',SALES_SHIPMENT:'销售发货',SALES_RETURN:'销售退货',LINE_RETURN:'生产退料',LINE_ISSUE:'生产领料',PENDING:'待处理',PROCESSING:'处理中',SUCCEEDED:'执行成功',FAILED:'执行失败',SKIPPED:'已跳过',WAITING:'待检验',BLOCKED:'不合格待复检',DONE:'已放行',SUGGESTED:'待确认',CONFIRMED:'已确认',CREATED:'已下发',IN_PROGRESS:'生产中',PRODUCTION_COMPLETED:'生产完成',RELEASED:'已放行',PROCESS:'过程检验',INCOMING:'来料检验',SHIPPING:'出货检验',IN:'入库',OUT:'出库'}
const display=(v:any,key:string)=>v===null?(['opening_quantity','closing_quantity'].includes(key)?'无法核实':'—'):(key.endsWith('_at')||key==='report_time')?String(v).replace('T',' ').slice(0,19):values[String(v)]||v
const columns=computed(()=>props.columns?.map(c=>c.key)||Array.from(new Set(props.rows.flatMap(r=>Object.keys(r)))).filter(k=>labels[k]))
const columnLabels=computed(()=>({...labels,...Object.fromEntries((props.columns||[]).map(c=>[c.key,c.label]))}))
</script>
<template><div class="overflow-x-auto border rounded-lg"><table class="min-w-full text-sm"><thead class="bg-slate-50"><tr><th v-for="c in columns" :key="c" class="text-left px-3 py-3 whitespace-nowrap">{{columnLabels[c]}}</th><th><slot name="heading"/></th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i" class="border-t"><td v-for="c in columns" :key="c" class="px-3 py-2 whitespace-nowrap">{{display(r[c],c)}}</td><td class="px-3 py-2"><slot :row="r"/></td></tr></tbody></table><p v-if="!rows.length" class="p-6 text-slate-500">当前条件下没有记录。</p></div></template>
